def to_heights(seq):
    depths = []
    cur_depth = 0
    for par in seq:
        if par == '[':
            depths.append(cur_depth)
            cur_depth += 1
        else:
            cur_depth -= 1
            depths.append(cur_depth)
    max_depth = max(depths)
    heights = [max_depth - depth for depth in depths]
    return heights


def to_strings(seq, heights):
    n_rows = 2 * (max(heights) + 1) + 1
    screen = Screen(n_rows)
    cur_x = 0
