", "class Screen:
    def __init__(self, n_rows):
        self.rows = [[] for _ in range(n_rows)]
        self.height = n_rows

    def draw(self, x, y, c):
        row = self.rows[y]
        while x > len(row) - 1:
            row.append(' ')
        row[x] = c

    def draw_open(self, x, height):
        middle = self.height // 2
        self.draw(x, middle, '|')
        for dy in range(1, height + 1):
            self.draw(x, middle + dy, '|')
            self.draw(x, middle - dy, '|')
        self.draw(x, middle + height + 1, '+')
        self.draw(x + 1, middle + height + 1, '-')
        self.draw(x, middle - height - 1, '+')
        self.draw(x + 1, middle - height - 1, '-')

    def draw_close(self, x, height):
        middle = self.height // 2
        self.draw(x, middle, '|')
        for dy in range(1, height + 1):
            self.draw(x, middle + dy, '|')
            self.draw(x, middle - dy, '|')
        self.draw(x, middle + height + 1, '+')
        self.draw(x - 1, middle + height + 1, '-')
        self.draw(x, middle - height - 1, '+')
        self.draw(x - 1, middle - height - 1, '-')

    def strings(self):
        return [''.join(row) for row in self.rows]


def to_heights(seq):
    depths = []
    cur_depth = 0
    for par in seq:
        if par == '[':
            depths.append(cur_depth)
            cur_depth += 1
        else:
            cur_depth -= 1
            depths.append(cur_depth)
    max_depth = max(depths)
    heights = [max_depth - depth for depth in depths]
    return heights


