        row[x] = c

    def draw_open(self, x, height):
        middle = self.height // 2
        self.draw(x, middle, '|')
        for dy in range(1, height + 1):
            self.draw(x, middle + dy, '|')
            self.draw(x, middle - dy, '|')
        self.draw(x, middle + height + 1, '+')
        self.draw(x + 1, middle + height + 1, '-')
        self.draw(x, middle - height - 1, '+')
        self.draw(x + 1, middle - height - 1, '-')

    def draw_close(self, x, height):
        middle = self.height // 2
        self.draw(x, middle, '|')
        for dy in range(1, height + 1):
            self.draw(x, middle + dy, '|')
            self.draw(x, middle - dy, '|')
        self.draw(x, middle + height + 1, '+')
        self.draw(x - 1, middle + height + 1, '-')
        self.draw(x, middle - height - 1, '+')
