    while curr_len < k:
        cnt[i] -= 1
        cnt[i - 1] += 2
        curr_len += 1
        i -= 1

    ans = []
    for i in sorted(list(cnt.keys()), reverse=True):
        ans.extend([i] * cnt[i])
    return ans

