    curr_len = len(cnt)
    curr_pow = len(as_bin) - 1

    if curr_len > k:
        return None

    while True:
        new_len = curr_len + cnt[curr_pow]
        if new_len > k:
            break
        cnt[curr_pow - 1] += 2 * cnt[curr_pow]
        del cnt[curr_pow]
        curr_pow -= 1
        curr_len = new_len

